package vn.hust.restaurant.service;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.*;import vn.hust.restaurant.repository.OrderRepository;public class OrderService{private final OrderRepository r;public OrderService(OrderRepository r){this.r=r;}public Optional<OrderSummary>active(int table)throws SQLException{return r.activeByTable(table);}public List<OrderSummary>open()throws SQLException{return r.openOrders();}public long create(int table,int employee)throws SQLException{return r.create(table,employee);}public void add(long order,int menu,int qty,String note)throws SQLException{r.addItem(order,menu,qty,note);}public List<OrderItemView>items(long order)throws SQLException{return r.items(order);}public void remove(long id)throws SQLException{r.removeItem(id);}public void send(long id)throws SQLException{r.sendKitchen(id);}public void ready(long id)throws SQLException{r.readyToPay(id);}public void cancel(long id)throws SQLException{r.cancel(id);}}
